"""The kitty's data, its storage in kitty.json, and all the money arithmetic.

Money is handled with Decimal and stored as strings, so there is never any
floating-point rounding drift. Every expense is converted to the main
currency when it is recorded, using the rate in effect at that moment, and
split into whole cents that always add up exactly to the converted amount.
"""

import json
import os
import re
import tempfile
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

DATA_FILE = "kitty.json"
FORMAT_VERSION = 1
CENT = Decimal("0.01")
DEFAULT_CATEGORY = "other"


class KittyError(Exception):
    """A problem the user can fix; reported as a message, not a traceback."""


_MONEY_RE = re.compile(r"^\d+(\.\d{1,2})?$")
_NUMBER_RE = re.compile(r"^\d+(\.\d+)?$")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
_CURRENCY_RE = re.compile(r"^[A-Za-z]{3}$")


# ---------------------------------------------------------------- parsing

def parse_money(text, what="amount"):
    """A positive amount with at most two decimals, e.g. "45" or "12.50"."""
    text = text.strip()
    if not _MONEY_RE.match(text):
        hint = " (use a dot for decimals, e.g. 12.50)" if "," in text else ""
        raise KittyError(
            f"{what} must be a positive number with at most two decimals, "
            f"got {text!r}{hint}"
        )
    value = Decimal(text)
    if value <= 0:
        raise KittyError(f"{what} must be greater than zero, got {text!r}")
    return value


def parse_number(text, what):
    """A positive number with any number of decimals, e.g. "0.9234"."""
    text = text.strip()
    if not _NUMBER_RE.match(text):
        hint = " (use a dot for decimals, e.g. 0.92)" if "," in text else ""
        raise KittyError(f"{what} must be a positive number, got {text!r}{hint}")
    value = Decimal(text)
    if value <= 0:
        raise KittyError(f"{what} must be greater than zero, got {text!r}")
    return value


def parse_date(text):
    text = text.strip()
    try:
        if not _DATE_RE.match(text):
            raise ValueError
        datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        raise KittyError(
            f"date must be a real date written YYYY-MM-DD, e.g. 2026-07-14, got {text!r}"
        ) from None
    return text


def today():
    return date.today().isoformat()


def parse_currency(text):
    text = text.strip()
    if not _CURRENCY_RE.match(text):
        raise KittyError(
            f"currency must be a three-letter code like EUR or USD, got {text!r}"
        )
    return text.upper()


def parse_category(text):
    text = text.strip().lower()
    if not text:
        raise KittyError("category can't be empty")
    return text


def fmt(value):
    """Money as text with exactly two decimals, never "-0.00"."""
    value = value.quantize(CENT, rounding=ROUND_HALF_UP)
    if value == 0:
        value = Decimal("0.00")
    return format(value, "f")


def convert(amount, rate):
    return (amount * rate).quantize(CENT, rounding=ROUND_HALF_UP)


def allocate(total, weights):
    """Split `total` into whole cents in proportion to `weights`.

    `weights` is a list of (name, positive number). The parts always add up
    to exactly `total`; leftover cents go to the largest fractional parts,
    and ties go to whoever comes first in the list.
    """
    cents = int(total / CENT)
    weight_sum = sum(Fraction(w) for _, w in weights)
    raw = [Fraction(cents) * Fraction(w) / weight_sum for _, w in weights]
    parts = [int(r) for r in raw]
    leftover = cents - sum(parts)
    by_remainder = sorted(range(len(raw)), key=lambda i: (-(raw[i] - parts[i]), i))
    for i in by_remainder[:leftover]:
        parts[i] += 1
    return {name: Decimal(c) * CENT for (name, _), c in zip(weights, parts)}


# ---------------------------------------------------------------- the kitty

class Kitty:
    def __init__(self, data):
        self.data = data

    # -- storage

    @classmethod
    def create(cls, base_currency, path=DATA_FILE):
        if os.path.exists(path):
            raise KittyError(
                f"there is already a kitty in this folder ({path}); "
                "delete or move it first if you really want to start over"
            )
        return cls({
            "version": FORMAT_VERSION,
            "base_currency": parse_currency(base_currency),
            "members": [],
            "rates": {},
            "next_expense_id": 1,
            "next_seq": 1,
            "expenses": [],
            "payments": [],
        })

    @classmethod
    def load(cls, path=DATA_FILE):
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except FileNotFoundError:
            raise KittyError(
                f"there's no {path} in this folder; start a kitty first with: "
                "python3 -m kitty init EUR"
            ) from None
        except (ValueError, UnicodeDecodeError):
            raise KittyError(f"{path} is damaged and can't be read as JSON") from None
        except OSError as e:
            raise KittyError(f"can't read {path}: {e.strerror}") from None
        required = ("base_currency", "members", "rates", "next_expense_id",
                    "next_seq", "expenses", "payments")
        if not isinstance(data, dict) or any(k not in data for k in required):
            raise KittyError(f"{path} doesn't look like a kitty file")
        if data.get("version") != FORMAT_VERSION:
            raise KittyError(f"{path} was made by a different version of kitty")
        return cls(data)

    def save(self, path=DATA_FILE):
        # Write to a temporary file and swap it in, so an interruption can
        # never leave a half-written kitty.json behind.
        folder = os.path.dirname(os.path.abspath(path))
        try:
            fd, tmp = tempfile.mkstemp(dir=folder, prefix=".kitty-", suffix=".tmp")
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as f:
                    json.dump(self.data, f, indent=2, ensure_ascii=False)
                    f.write("\n")
                os.replace(tmp, path)
            except BaseException:
                if os.path.exists(tmp):
                    os.remove(tmp)
                raise
        except OSError as e:
            raise KittyError(f"can't save {path}: {e.strerror}") from None

    # -- basics

    @property
    def base(self):
        return self.data["base_currency"]

    @property
    def members(self):
        return self.data["members"]

    def _next_seq(self):
        seq = self.data["next_seq"]
        self.data["next_seq"] = seq + 1
        return seq

    def require_member(self, name):
        name = name.strip()
        if name in self.members:
            return name
        close = [m for m in self.members if m.lower() == name.lower()]
        if close:
            raise KittyError(f"{name!r} isn't in the group; did you mean {close[0]!r}?")
        group = ", ".join(self.members) if self.members else "nobody yet"
        raise KittyError(f"{name!r} isn't in the group (members: {group})")

    def _order(self, names):
        """Names sorted into the order members were added."""
        return sorted(names, key=self.members.index)

    # -- members

    def add_member(self, name):
        name = name.strip()
        if not name:
            raise KittyError("name can't be empty")
        if "," in name or "=" in name:
            raise KittyError("name can't contain ',' or '=' (they're used in --among and --exact)")
        if name.startswith("-"):
            raise KittyError("name can't start with '-'")
        for m in self.members:
            if m.lower() == name.lower():
                raise KittyError(f"{m!r} is already in the group")
        self.members.append(name)
        return name

    def remove_member(self, name):
        name = self.require_member(name)
        involved = sum(
            1 for e in self.data["expenses"] if e["payer"] == name or name in e["shares"]
        ) + sum(
            1 for p in self.data["payments"] if name in (p["from"], p["to"])
        )
        if involved:
            raise KittyError(
                f"{name} is part of {involved} expense(s)/payment(s), so removing "
                "them would make the totals wrong; remove those first"
            )
        self.members.remove(name)
        return name

    # -- rates

    def set_rate(self, currency, rate):
        currency = parse_currency(currency)
        if currency == self.base:
            raise KittyError(f"{currency} is the main currency; its rate is always 1")
        rate = parse_number(rate, "rate")
        self.data["rates"][currency] = str(rate)
        return currency, rate

    def rate_for(self, currency):
        if currency == self.base:
            return Decimal(1)
        if currency not in self.data["rates"]:
            raise KittyError(
                f"there's no exchange rate for {currency} yet; set one first, e.g.: "
                f"python3 -m kitty rate set {currency} 0.92"
            )
        return Decimal(self.data["rates"][currency])

    def _to_base(self, amount, currency):
        base_amount = convert(amount, self.rate_for(currency))
        if base_amount <= 0:
            raise KittyError(f"{amount} {currency} is worth less than one cent in {self.base}")
        return base_amount

    # -- expenses

    def _names(self, text):
        names = [part.strip() for part in text.split(",")]
        if any(not n for n in names):
            raise KittyError(f"there's an empty name in {text!r}")
        names = [self.require_member(n) for n in names]
        dupes = sorted({n for n in names if names.count(n) > 1})
        if dupes:
            raise KittyError(f"{', '.join(dupes)} is listed more than once")
        return names

    def _assignments(self, text, option, parse_value):
        pairs = []
        for part in text.split(","):
            if "=" not in part:
                raise KittyError(f"{option} needs NAME=VALUE pairs separated by commas, got {part.strip()!r}")
            name, value = part.split("=", 1)
            pairs.append((name, value))
        names = self._names(",".join(n for n, _ in pairs))
        return [(n, parse_value(v, f"{option} value for {n}")) for n, (_, v) in zip(names, pairs)]

    def add_expense(self, payer, amount, description, currency=None, when=None,
                    category=None, among=None, exact=None, shares=None, percent=None):
        payer = self.require_member(payer)
        amount = parse_money(amount)
        description = description.strip()
        if not description:
            raise KittyError("description can't be empty")
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when) if when else today()
        category = parse_category(category) if category else DEFAULT_CATEGORY
        base_amount = self._to_base(amount, currency)

        if exact is not None:
            weights = self._assignments(exact, "--exact", parse_money)
            total = sum(v for _, v in weights)
            if total != amount:
                raise KittyError(
                    f"--exact amounts add up to {fmt(total)} but the expense is "
                    f"{fmt(amount)} {currency}"
                )
        elif shares is not None:
            weights = self._assignments(shares, "--shares", parse_number)
        elif percent is not None:
            weights = self._assignments(percent, "--percent", parse_number)
            total = sum(v for _, v in weights)
            if total != 100:
                raise KittyError(f"--percent values add up to {total}, not 100")
        else:
            names = self._names(among) if among is not None else list(self.members)
            if not names:
                raise KittyError("there's nobody in the group to split this between; add members first")
            weights = [(n, 1) for n in names]

        order = {n: i for i, n in enumerate(self._order([n for n, _ in weights]))}
        weights.sort(key=lambda nw: order[nw[0]])
        split = allocate(base_amount, weights)

        expense_id = self.data["next_expense_id"]
        self.data["next_expense_id"] = expense_id + 1
        self.data["expenses"].append({
            "id": expense_id,
            "seq": self._next_seq(),
            "date": when,
            "payer": payer,
            "description": description,
            "amount": str(amount),
            "currency": currency,
            "rate": str(self.rate_for(currency)),
            "base_amount": str(base_amount),
            "category": category,
            "shares": {n: str(v) for n, v in split.items()},
        })
        return expense_id

    def remove_expense(self, expense_id):
        try:
            wanted = int(expense_id)
        except ValueError:
            raise KittyError(f"expense ID must be a whole number, got {expense_id!r}") from None
        for e in self.data["expenses"]:
            if e["id"] == wanted:
                self.data["expenses"].remove(e)
                return e
        raise KittyError(f"there's no expense with ID {wanted} (see: python3 -m kitty expense list)")

    def expense_list(self):
        return [
            {
                "id": e["id"],
                "date": e["date"],
                "payer": e["payer"],
                "description": e["description"],
                "amount": fmt(Decimal(e["amount"])),
                "currency": e["currency"],
                "base_amount": fmt(Decimal(e["base_amount"])),
                "category": e["category"],
                "shares": {n: fmt(Decimal(v)) for n, v in e["shares"].items()},
            }
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]

    # -- payments

    def add_payment(self, sender, receiver, amount, currency=None, when=None):
        sender = self.require_member(sender)
        receiver = self.require_member(receiver)
        if sender == receiver:
            raise KittyError("a payment needs two different people")
        amount = parse_money(amount)
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when) if when else today()
        base_amount = self._to_base(amount, currency)
        self.data["payments"].append({
            "seq": self._next_seq(),
            "date": when,
            "from": sender,
            "to": receiver,
            "amount": str(amount),
            "currency": currency,
            "rate": str(self.rate_for(currency)),
            "base_amount": str(base_amount),
        })
        return base_amount

    # -- reports

    def _timeline(self):
        """(date, description, {name: change}) for everything, oldest first."""
        events = []
        for e in self.data["expenses"]:
            changes = {e["payer"]: Decimal(e["base_amount"])}
            for n, v in e["shares"].items():
                changes[n] = changes.get(n, Decimal(0)) - Decimal(v)
            events.append((e["date"], e["seq"], e["description"], changes))
        for p in self.data["payments"]:
            amount = Decimal(p["base_amount"])
            changes = {p["from"]: amount, p["to"]: -amount}
            events.append((p["date"], p["seq"], f"Payment from {p['from']} to {p['to']}", changes))
        events.sort(key=lambda ev: (ev[0], ev[1]))
        return [(d, desc, changes) for d, _, desc, changes in events]

    def balances(self):
        totals = {n: Decimal(0) for n in self.members}
        for _, _, changes in self._timeline():
            for n, v in changes.items():
                totals[n] = totals.get(n, Decimal(0)) + v
        return totals

    def settle(self):
        cents = {n: int(v / CENT) for n, v in self.balances().items()}
        rank = {n: i for i, n in enumerate(self.members)}
        creditors = sorted(([n, c] for n, c in cents.items() if c > 0),
                           key=lambda x: (-x[1], rank.get(x[0], 0)))
        debtors = sorted(([n, -c] for n, c in cents.items() if c < 0),
                         key=lambda x: (-x[1], rank.get(x[0], 0)))
        transfers = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            pay = min(debtors[i][1], creditors[j][1])
            transfers.append({"from": debtors[i][0], "to": creditors[j][0],
                              "amount": fmt(Decimal(pay) * CENT)})
            debtors[i][1] -= pay
            creditors[j][1] -= pay
            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1
        return transfers

    def history(self, name):
        name = self.require_member(name)
        running = Decimal(0)
        rows = []
        for when, description, changes in self._timeline():
            if name in changes:
                running += changes[name]
                rows.append({"date": when, "description": description,
                             "change": fmt(changes[name]), "balance": fmt(running)})
        return rows

    def report(self):
        spent = {}
        for e in self.data["expenses"]:
            per_person = spent.setdefault(e["category"], {})
            for n, v in e["shares"].items():
                per_person[n] = per_person.get(n, Decimal(0)) + Decimal(v)
        rank = {n: i for i, n in enumerate(self.members)}
        return {
            category: {n: fmt(spent[category][n])
                       for n in sorted(spent[category], key=lambda n: rank.get(n, 0))}
            for category in sorted(spent)
        }

    def export_rows(self):
        return [
            {
                "id": e["id"],
                "date": e["date"],
                "payer": e["payer"],
                "description": e["description"],
                "amount": fmt(Decimal(e["amount"])),
                "currency": e["currency"],
                "category": e["category"],
                "base_amount": fmt(Decimal(e["base_amount"])),
            }
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]

