            raise KittyError("name can't start with '-'")
        for m in self.members:
            if m.lower() == name.lower():
                raise KittyError(f"{m!r} is already in the group")
        self.members.append(name)
        return name

    def remove_member(self, name):
        name = self.require_member(name)
        involved = sum(
            1 for e in self.data["expenses"] if e["payer"] == name or name in e["shares"]
        ) + sum(
            1 for p in self.data["payments"] if name in (p["from"], p["to"])
        )
        if involved:
            raise KittyError(
                f"{name} is part of {involved} expense(s)/payment(s), so removing "
                "them would make the totals wrong; remove those first"
            )
        self.members.remove(name)
        return name

    # -- rates

    def set_rate(self, currency, rate):
        currency = parse_currency(currency)
        if currency == self.base:
            raise KittyError(f"{currency} is the main currency; its rate is always 1")
        rate = parse_number(rate, "rate")
        self.data["rates"][currency] = str(rate)
        return currency, rate

    def rate_for(self, currency):
        if currency == self.base:
            return Decimal(1)
        if currency not in self.data["rates"]:
            raise KittyError(
                f"there's no exchange rate for {currency} yet; set one first, e.g.: "
                f"python3 -m kitty rate set {currency} 0.92"
            )
        return Decimal(self.data["rates"][currency])

    def _to_base(self, amount, currency):
        base_amount = convert(amount, self.rate_for(currency))
        if base_amount <= 0:
            raise KittyError(f"{amount} {currency} is worth less than one cent in {self.base}")
        return base_amount

    # -- expenses

    def _names(self, text):
        names = [part.strip() for part in text.split(",")]
        if any(not n for n in names):
            raise KittyError(f"there's an empty name in {text!r}")
        names = [self.require_member(n) for n in names]
        dupes = sorted({n for n in names if names.count(n) > 1})
        if dupes:
            raise KittyError(f"{', '.join(dupes)} is listed more than once")
        return names

    def _assignments(self, text, option, parse_value):
        pairs = []
        for part in text.split(","):
            if "=" not in part:
                raise KittyError(f"{option} needs NAME=VALUE pairs separated by commas, got {part.strip()!r}")
            name, value = part.split("=", 1)
            pairs.append((name, value))
        names = self._names(",".join(n for n, _ in pairs))
        return [(n, parse_value(v, f"{option} value for {n}")) for n, (_, v) in zip(names, pairs)]

    def add_expense(self, payer, amount, description, currency=None, when=None,
                    category=None, among=None, exact=None, shares=None, percent=None):
        payer = self.require_member(payer)
        amount = parse_money(amount)
        description = description.strip()
        if not description:
            raise KittyError("description can't be empty")
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when) if when else today()
        category = parse_category(category) if category else DEFAULT_CATEGORY
        base_amount = self._to_base(amount, currency)

        if exact is not None:
            weights = self._assignments(exact, "--exact", parse_money)
            total = sum(v for _, v in weights)
            if total != amount:
                raise KittyError(
                    f"--exact amounts add up to {fmt(total)} but the expense is "
                    f"{fmt(amount)} {currency}"
                )
        elif shares is not None:
            weights = self._assignments(shares, "--shares", parse_number)
        elif percent is not None:
            weights = self._assignments(percent, "--percent", parse_number)
            total = sum(v for _, v in weights)
            if total != 100:
                raise KittyError(f"--percent values add up to {total}, not 100")
        else:
            names = self._names(among) if among is not None else list(self.members)
            if not names:
                raise KittyError("there's nobody in the group to split this between; add members first")
            weights = [(n, 1) for n in names]

        order = {n: i for i, n in enumerate(self._order([n for n, _ in weights]))}
        weights.sort(key=lambda nw: order[nw[0]])
        split = allocate(base_amount, weights)

        expense_id = self.data["next_expense_id"]
        self.data["next_expense_id"] = expense_id + 1
        self.data["expenses"].append({
            "id": expense_id,
            "seq": self._next_seq(),
            "date": when,
            "payer": payer,
            "description": description,
            "amount": str(amount),
            "currency": currency,
            "rate": str(self.rate_for(currency)),
            "base_amount": str(base_amount),
            "category": category,
            "shares": {n: str(v) for n, v in split.items()},
        })
        return expense_id

    def remove_expense(self, expense_id):
        try:
            wanted = int(expense_id)
        except ValueError:
            raise KittyError(f"expense ID must be a whole number, got {expense_id!r}") from None
        for e in self.data["expenses"]:
            if e["id"] == wanted:
                self.data["expenses"].remove(e)
                return e
        raise KittyError(f"there's no expense with ID {wanted} (see: python3 -m kitty expense list)")

    def expense_list(self):
        return [
            {
                "id": e["id"],
                "date": e["date"],
                "payer": e["payer"],
                "description": e["description"],
                "amount": fmt(Decimal(e["amount"])),
                "currency": e["currency"],
                "base_amount": fmt(Decimal(e["base_amount"])),
                "category": e["category"],
                "shares": {n: fmt(Decimal(v)) for n, v in e["shares"].items()},
            }
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]

    # -- payments

    def add_payment(self, sender, receiver, amount, currency=None, when=None):
        sender = self.require_member(sender)
        receiver = self.require_member(receiver)
        if sender == receiver:
            raise KittyError("a payment needs two different people")
        amount = parse_money(amount)
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when) if when else today()
        base_amount = self._to_base(amount, currency)
        self.data["payments"].append({
            "seq": self._next_seq(),
            "date": when,
            "from": sender,
            "to": receiver,
            "amount": str(amount),
            "currency": currency,
            "rate": str(self.rate_for(currency)),
            "base_amount": str(base_amount),
        })
        return base_amount

    # -- reports

    def _timeline(self):
        """(date, description, {name: change}) for everything, oldest first."""
        events = []
        for e in self.data["expenses"]:
            changes = {e["payer"]: Decimal(e["base_amount"])}
            for n, v in e["shares"].items():
                changes[n] = changes.get(n, Decimal(0)) - Decimal(v)
            events.append((e["date"], e["seq"], e["description"], changes))
        for p in self.data["payments"]:
            amount = Decimal(p["base_amount"])
            changes = {p["from"]: amount, p["to"]: -amount}
            events.append((p["date"], p["seq"], f"Payment from {p['from']} to {p['to']}", changes))
        events.sort(key=lambda ev: (ev[0], ev[1]))
        return [(d, desc, changes) for d, _, desc, changes in events]

    def balances(self):
        totals = {n: Decimal(0) for n in self.members}
        for _, _, changes in self._timeline():
            for n, v in changes.items():
                totals[n] = totals.get(n, Decimal(0)) + v
        return totals

    def settle(self):
        cents = {n: int(v / CENT) for n, v in self.balances().items()}
        rank = {n: i for i, n in enumerate(self.members)}
        creditors = sorted(([n, c] for n, c in cents.items() if c > 0),
                           key=lambda x: (-x[1], rank.get(x[0], 0)))
        debtors = sorted(([n, -c] for n, c in cents.items() if c < 0),
                         key=lambda x: (-x[1], rank.get(x[0], 0)))
        transfers = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            pay = min(debtors[i][1], creditors[j][1])
            transfers.append({"from": debtors[i][0], "to": creditors[j][0],
                              "amount": fmt(Decimal(pay) * CENT)})
            debtors[i][1] -= pay
            creditors[j][1] -= pay
            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1
        return transfers

    def history(self, name):
        name = self.require_member(name)
        running = Decimal(0)
        rows = []
        for when, description, changes in self._timeline():
            if name in changes:
                running += changes[name]
                rows.append({"date": when, "description": description,
                             "change": fmt(changes[name]), "balance": fmt(running)})
        return rows

    def report(self):
        spent = {}
        for e in self.data["expenses"]:
            per_person = spent.setdefault(e["category"], {})
            for n, v in e["shares"].items():
                per_person[n] = per_person.get(n, Decimal(0)) + Decimal(v)
        rank = {n: i for i, n in enumerate(self.members)}
        return {
            category: {n: fmt(spent[category][n])
                       for n in sorted(spent[category], key=lambda n: rank.get(n, 0))}
            for category in sorted(spent)
        }

    def export_rows(self):
        return [
            {
                "id": e["id"],
                "date": e["date"],
                "payer": e["payer"],
                "description": e["description"],
                "amount": fmt(Decimal(e["amount"])),
                "currency": e["currency"],
                "category": e["category"],
                "base_amount": fmt(Decimal(e["base_amount"])),
            }
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]

